<script lang="ts">
 import {untrack} from 'svelte';
 import type {ToolState} from '../../types';
 import Result from '../../components/Result.svelte';
 let {state:data=$bindable()}: {state:ToolState} = $props();
 import {onDestroy} from 'svelte';import {workerTask} from '../../worker-task';import Worker from './file.worker?worker';import {download} from '../../browser-files';let busy=$state(false),error=$state('');const controller=new AbortController();onDestroy(()=>controller.abort());import {renameFiles} from './logic';untrack(()=>{data.files??=[];data.options??={prefix:'写真_',suffix:'',find:'',replacement:'',number:true,start:1,pad:3};});
 let result=$derived.by(()=>{try{return {names:data.files.length?renameFiles(data.files.map((f:File)=>f.name),data.options):[],error:''};}catch(e){return {names:[],error:(e as Error).message};}});
 function select(e:Event){const files=[...((e.target as HTMLInputElement).files||[])];if(files.length>200||files.reduce((n,f)=>n+f.size,0)>50*1024*1024){error='200ファイル・合計50MB以内で選択してください。';return;}error='';data.files=files;}
 async function save(){busy=true;error='';try{const bytes=await workerTask<Uint8Array>(new Worker(),data.files.map((file:File,i:number)=>({file,name:result.names[i]})),controller.signal);download(new Blob([bytes as BlobPart],{type:'application/zip'}),'renamed.zip');}catch(e){error=(e as Error).message;}finally{busy=false;}}
 
</script>
<p class="tool-note">元ファイルの名前や内容は変更できません。変更した名前のコピーをZIPで保存します。</p><label>複数ファイル<input type="file" multiple disabled={busy} onchange={select}/></label><div class="form-grid">{#each [['prefix','プレフィックス'],['suffix','サフィックス'],['find','置換する文字（拡張子以外）'],['replacement','置換後']] as [key,label]}<label>{label}<input bind:value={data.options[key]} maxlength="100"/></label>{/each}<label>連番開始<input type="number" min="0" max="999999" bind:value={data.options.start}/></label><label>連番桁数<input type="number" min="1" max="6" bind:value={data.options.pad}/></label></div><label><input type="checkbox" bind:checked={data.options.number}/>連番を付ける</label>{#if result.error||error}<p class="error" role="alert">{result.error||error}</p>{/if}<div style="overflow:auto"><table class="utility-table"><thead><tr><th>変更前</th><th>変更後</th></tr></thead><tbody>{#each data.files as file,i}<tr><td style="overflow-wrap:anywhere">{file.name}</td><td style="overflow-wrap:anywhere">{result.names[i]||'—'}</td></tr>{/each}</tbody></table></div><button class="primary" disabled={busy||!result.names.length||!!result.error} onclick={save}>{busy?'ZIP作成中…':'ZIPを保存'}</button><p class="tool-note">例：a.jpg → 写真_a001.jpg。最大200ファイル・合計50MB。ZIPは無圧縮で元の内容を保持。名前の大文字小文字・Unicode正規化による重複も拒否します。</p>
